// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    RewardVault c;

    function setUp() public {
        c = new RewardVault();
    }

    function testFuzz_property(uint256 depositAmount, address depositor) public {
        vm.assume(depositor != address(0));
        vm.assume(depositAmount > 0);
        vm.deal(depositor, depositAmount);

        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        assertEq(c.balance(depositor), depositAmount);
    }
}
